package chat.oldy;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import java.io.*;import java.net.*;import javax.net.ssl.*;

/** Emulator-only integration: real TUN DNS/UDP and opaque TLS to the official YouTube host.
 * This is not a claim of Wi-Fi, cellular, QUIC playback or handset verification. */
public class LocalTunnelInstrumentation extends Instrumentation {
 public void onCreate(Bundle b){start();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(cmd);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();MainActivity a=null;try{a=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2900);shell("appops set chat.oldy ACTIVATE_VPN allow");check(android.net.VpnService.prepare(c)==null,"Emulator VPN permission fixture failed");MainActivity activity=a;runOnMainSync(()->LocalTunnelService.start(activity));long end=System.currentTimeMillis()+10000;while(!TunnelStateRepository.on()&&System.currentTimeMillis()<end)Thread.sleep(100);check(TunnelStateRepository.on(),"Local TUN failed: "+TunnelStateRepository.lastError(c));Thread.sleep(1700);check(TunnelStateRepository.on(),"Native TUN exited after startup");
  InetAddress[] addresses=InetAddress.getAllByName("www.youtube.com");boolean v4=false,v6=false;InetAddress ipv6=null;for(InetAddress ip:addresses){String text=ip.getHostAddress();v4|=text.startsWith("198.18.");if(ip instanceof Inet6Address&&text.startsWith("fd66:")){v6=true;ipv6=ip;}}check(v4,"YouTube DNS did not enter local TUN");
  HttpsURLConnection request=(HttpsURLConnection)new URL("https://www.youtube.com/").openConnection();request.setConnectTimeout(20000);request.setReadTimeout(15000);request.setRequestMethod("HEAD");request.setInstanceFollowRedirects(false);int response;try{response=request.getResponseCode();}finally{request.disconnect();}check(response>=200&&response<600,"TLS through local TUN failed");
  if(ipv6!=null){try(Socket socket=new Socket()){socket.connect(new InetSocketAddress(ipv6,443),15000);try(SSLSocket tls=(SSLSocket)((SSLSocketFactory)SSLSocketFactory.getDefault()).createSocket(socket,"www.youtube.com",443,true)){SSLParameters params=tls.getSSLParameters();params.setEndpointIdentificationAlgorithm("HTTPS");tls.setSSLParameters(params);tls.setSoTimeout(15000);tls.startHandshake();}}}
  Thread.sleep(1800);check(TunnelStateRepository.on()&&TunnelStateRepository.txBytes>0&&TunnelStateRepository.rxBytes>0,"Native TUN traffic counters did not advance");runOnMainSync(()->LocalTunnelService.stop(activity));end=System.currentTimeMillis()+8000;while((TunnelStateRepository.on()||NetworkDiagnostics.otherVpn(c))&&System.currentTimeMillis()<end)Thread.sleep(100);check(!TunnelStateRepository.on(),"Local VPN did not stop");check(!NetworkDiagnostics.otherVpn(c),"VPN routes survived service stop");
  runOnMainSync(()->LocalTunnelService.start(activity));end=System.currentTimeMillis()+10000;while(!TunnelStateRepository.on()&&System.currentTimeMillis()<end)Thread.sleep(100);check(TunnelStateRepository.on(),"Local VPN failed to restart after cleanup");Thread.sleep(1700);check(TunnelStateRepository.on(),"Restarted native module exited");runOnMainSync(()->LocalTunnelService.stop(activity));end=System.currentTimeMillis()+8000;while((TunnelStateRepository.on()||NetworkDiagnostics.otherVpn(c))&&System.currentTimeMillis()<end)Thread.sleep(100);check(!NetworkDiagnostics.otherVpn(c),"Restarted VPN did not remove routes");
  result.putString("stream","OLDY_LOCAL_TUNNEL_PASS: native per-app split TUN, synthetic DNS over UDP, protected direct TCP/TLS, IPv6="+v6+", packet counters, service cleanup and restart; physical networks need handset validation\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream","OLDY_LOCAL_TUNNEL_FAIL: "+android.util.Log.getStackTraceString(e));finish(0,result);}finally{LocalTunnelService.stop(c);}}
}
